const results = $input.first().json.results || [];

// Filter to today's memories only
const today = new Date().toISOString().slice(0, 10);
const todayMemories = results.filter(r => r.created_at && r.created_at.startsWith(today));

if (todayMemories.length < 3) {
  // Not enough memories for a meaningful reflection
  return [];
}

const summaryLines = todayMemories.map((m, i) => 
  `${i+1}. [${m.category}] ${m.content.substring(0, 200)}`
).join('\n');

const prompt = `You are a reflection assistant. Review these memories from today and write a concise daily reflection (3-5 sentences). Focus on patterns, decisions, and what was accomplished. Do not list items individually.\n\nToday's memories:\n${summaryLines}\n\nDaily reflection:`;

return [{ json: { prompt, memory_count: todayMemories.length } }];

const ollamaResp = $input.first().json;
const content = ollamaResp.choices?.[0]?.message?.content || '';
const memCount = $('Build Reflection Prompt').first().json.memory_count;

if (!content || content.length < 20) {
  return []; // Skip empty reflections
}

return [{ json: {
  content: content.trim(),
  memory_count: memCount
}}];
